# 记忆化搜索框架
@lru_cache
def dfs(pos, ..., lim, lead):
  if pos == 0: return 1  # 所有位都处理完
  if not lim and not lead and f[pos][...] != -1:
    return f[pos][...]
  upper = digits[pos] if lim else 9
  ans = 0
  for d in 0..upper:
    ans += dfs(pos-1, ..., lim and d==upper, lead and d==0)
  if not lim and not lead: f[pos][...] = ans
  return ans
